add_action( 'woocommerce_new_order', 'perfectpixel_cheap_orders_count', 20, 2 );
add_filter( 'woocommerce_is_purchasable', 'perfectpixel_cheap_orders_limit', 30, 2 );

function perfectpixel_cheap_orders_key() {
	return 'perfectpixel_cheap_orders_' . current_time( 'Ymd' );
}

function perfectpixel_is_cheap( $product ) {
	$price = $product ? $product->get_price() : '';
	return '' !== $price && (float) $price > 0 && (float) $price <= (float) '{{cheap_price_threshold}}';
}

function perfectpixel_cheap_orders_count( $order_id, $order = null ) {
	$order = $order ? $order : wc_get_order( $order_id );
	if ( ! $order ) {
		return;
	}
	foreach ( $order->get_items() as $item ) {
		if ( perfectpixel_is_cheap( $item->get_product() ) ) {
			set_transient( perfectpixel_cheap_orders_key(), (int) get_transient( perfectpixel_cheap_orders_key() ) + 1, DAY_IN_SECONDS );
			return;
		}
	}
}

function perfectpixel_cheap_orders_limit( $purchasable, $product ) {
	if ( $purchasable && ! is_admin() && perfectpixel_is_cheap( $product ) && (int) get_transient( perfectpixel_cheap_orders_key() ) >= max( 1, (int) '{{cheap_daily_orders}}' ) ) {
		return false;
	}
	return $purchasable;
}
